    public static IReadOnlyList<ReligiousIdea> Ideas => Traditions.SelectMany(item => item.Ideas).ToArray();

    public static ReligiousTraditionKnowledge? FindTradition(string keyOrName) =>
        Traditions.FirstOrDefault(item =>
            item.Key.Equals(keyOrName, StringComparison.OrdinalIgnoreCase) ||
            item.Name.Equals(keyOrName, StringComparison.OrdinalIgnoreCase));

    private static ReligiousTraditionKnowledge T(string key, string name, string family, string sourceBasis, params ReligiousIdea[] ideas) =>
        new(key, name, family, sourceBasis, TruthStatus, ideas);

    private static ReligiousIdea I(string topic, string summary, params string[] relatedChoiceKeys) =>
        new(topic, summary, relatedChoiceKeys);
