public sealed record ReligiousTraditionKnowledge(
    string Key,
    string Name,
    string Family,
    string SourceBasis,
    string TruthStatus,
    IReadOnlyList<ReligiousIdea> Ideas);

public sealed record ReligiousIdea(
    string Topic,
    string Summary,
    IReadOnlyList<string> RelatedChoiceKeys);
